export function getHomeTemplate(){return`\n        <h1>Página Inicial</h1>\n        <p>Bem-vindo à nossa Single Page Application. Navegue pelo menu acima.</p>\n        <hr style="margin: 20px 0; border-color: #ccc;">\n        ${getListaUsuariosTemplate()}\n    `}export function getFormTemplate(){return'\n        <h1>Cadastro de Usuário</h1>\n        <form id="form-cadastro">\n            <label for="nome-usuario">Nome do Usuário:</label>\n            <input type="text" id="nome-usuario" name="nome-usuario" placeholder="Digite seu nome" aria-required="true" required>\n            \n            <button type="submit" aria-label="Salvar cadastro de usuário">Salvar no LocalStorage</button>\n            <p id="mensagem-feedback"></p>\n        </form>\n    '}export function getListaUsuariosTemplate(){const e=JSON.parse(localStorage.getItem("usuarios"))||[];let a="\n        <h2>Usuários Cadastrados</h2>\n        <p>Abaixo está a lista de usuários processada dinamicamente:</p>\n    ";return e.length>0?a+=`\n            <ul style="margin-top: 20px; list-style-type: square; padding-left: 20px;">\n                ${e.map(e=>`<li><strong>${e}</strong></li>`).join("")}\n            </ul>\n        `:a+='<p style="color: red; margin-top: 10px;">Nenhum usuário cadastrado ainda.</p>',a}